    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacing-md);
}

main {
    width: 100%;
}

.container {
    width: 100%;
    max-width: 500px;
    margin: 0 auto;
    background-color: var(--color-bg);
    padding: var(--spacing-lg);
    border-radius: var(--radius);
    box-shadow: var(--shadow-md);
}

h1 {
    font-size: 1.75rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
    color: var(--color-text);
}

.intro-text {
    font-size: 1rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-lg);
}

form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xs);
}

input[type="checkbox"] {
    margin: 0;
    width: 20px;
    height: 20px;
    cursor: pointer;
    accent-color: var(--color-primary);
    flex-shrink: 0;
}

/* Combine checkbox and label in a row */
.form-field label {
    display: flex;
    gap: var(--spacing-sm);
    align-items: flex-start;
    cursor: pointer;
    font-size: 1rem;
    color: var(--color-text);
    line-height: 1.5;
}

.form-field label a {
    color: var(--color-primary);
    text-decoration: none;
    font-weight: 500;
}

.form-field label a:hover {
    text-decoration: underline;
}

.form-field label a:focus {
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
    border-radius: 2px;
}

.form-field span[aria-hidden="true"] {
    color: var(--color-error);
    margin-left: 0.125rem;
}

.help-text {
    font-size: 0.875rem;
    color: var(--color-text-secondary);
    margin-left: calc(20px + var(--spacing-sm));
}

.error-text {
    font-size: 0.875rem;
    color: var(--color-error);
    margin-left: calc(20px + var(--spacing-sm));
    font-weight: 500;
}

input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
}

input[type="checkbox"]:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}

input[type="checkbox"][aria-invalid="true"] {
    outline: 2px solid var(--color-error);
    outline-offset: 0px;
}

input[type="checkbox"][aria-invalid="true"]:focus-visible {
    outline: 2px solid var(--color-error);
    outline-offset: 2px;
}

.submit-btn {
    background-color: var(--color-primary);
    color: white;
    border: none;
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--radius);
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: var(--spacing-sm);
    min-height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.submit-btn:hover:not(:disabled) {
    background-color: var(--color-primary-hover);
    box-shadow: var(--shadow-md);
}

.submit-btn:active:not(:disabled) {
    background-color: var(--color-primary-focus);
}

.submit-btn:focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
}

.submit-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.submit-btn.success {
    background-color: var(--color-success);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* High contrast mode */
@media (prefers-contrast: more) {
    input[type="checkbox"] {
        outline: 1px solid var(--color-text);
    }

    .submit-btn {
        border: 2px solid var(--color-primary);
    }
}

/* Responsive design */
@media (max-width: 480px) {
    .container {
        padding: var(--spacing-md);
    }

    h1 {
        font-size: 1.5rem;
    }

    .intro-text {
        font-size: 0.95rem;
    }
}

/* Forced colors mode */
@media (forced-colors: active) {
    .container {
        border: 1px solid CanvasText;
    }

    input[type="checkbox"] {
        border: 2px solid CanvasText;
    }

    input[type="checkbox"]:focus-visible {
        outline: 2px solid Highlight;
    }

    .submit-btn {
        border: 2px solid ButtonText;
    }

    .submit-btn:focus-visible {
        outline: 2px solid Highlight;
    }
}
